/** @jsxImportSource kerfjs */
import { delegate } from 'kerfjs';
import { TokenSearchField, readTokenSearchField, placeTokenSearchCaret } from '@kerfjs/ui/token-search-field';
import '@kerfjs/ui/layout.css';
import './tokenized-search.css';

export type Filter = { id: string; label: string; expression: string };
type Snapshot = ReturnType<typeof readTokenSearchField>;
export type Query = { text: string; tokens: Filter[] };
type Suggestion = { id: string; label: string; expression: string };
export interface SearchPolicy {
  // Domain parsing and suggestions live in the application; the UI package
  // neither interprets expressions nor contacts a search service.
  parse(snapshot: Snapshot, currentTokens: Filter[]): Query;
  suggest(expression: string): Suggestion[];
  search(query: Query): void;
}
export function createSearchEditor(id: string, policy: SearchPolicy) {
  let query: Query = { text: '', tokens: [] };
  let editing: string | null = null;
  let draft = '';
  let suggestions: Suggestion[] = [];
  let announcement = '';
  let sequence = 0;
  let invalidate = () => {};
  let root: HTMLElement | undefined;
  const editor = () => root?.querySelector<HTMLElement>('#' + CSS.escape(id) + ' [role="searchbox"]');
  function capture() {
    const field = editor();
    if (field) query = policy.parse(readTokenSearchField(field), query.tokens);
  }
  function restoreCaret() {
    const field = editor();
    if (field) { field.focus(); placeTokenSearchCaret(field); }
  }
  function commit() {
    invalidate(); // Host renders synchronously before caret restoration.
    restoreCaret();
    policy.search(query);
  }
  const render = () => <section class="filter-search kui-layout kui-section-stack">
    <TokenSearchField id={id} label="Search workspace tasks" text={query.text}
      tokens={query.tokens.map(token => ({ id: token.id, label: token.label }))}
      clearAction="search.clear" editAction="search.token.edit" removeAction="search.token.remove" />
    <div class="kui-control-cluster">
      <button class="search-button" type="button" data-action="search.filter.add">Add filter</button>
      <button class="search-button" type="button" data-action="search.submit">Search</button>
    </div>
    {editing !== null && <div class="filter-edit kui-surface-body kui-section-stack" role="group" aria-label="Edit search filter">
      <label for={id + '-expression'}>Filter expression</label>
      <input id={id + '-expression'} data-filter-expression value={draft} aria-describedby={id + '-hint'} />
      <p id={id + '-hint'}>Choose a suggestion below, or enter an expression. Enter applies; Escape cancels.</p>
      <ul aria-label="Filter suggestions">{suggestions.map(suggestion => <li>
        <button class="search-button" type="button" data-action="search.suggestion" data-suggestion-id={suggestion.id}>{suggestion.label}</button>
      </li>)}</ul>
      <div class="kui-control-cluster">
        <button class="search-button" type="button" data-action="search.filter.apply">Apply filter</button>
        <button class="search-button" type="button" data-action="search.filter.cancel">Cancel</button>
      </div>
    </div>}
    <p role="status" aria-live="polite">{announcement}</p>
  </section>;
  function applyFilter(expression = draft, label = expression) {
    if (!expression.trim()) { announcement = 'Enter a filter expression.'; invalidate(); return; }
    capture();
    const existing = query.tokens.findIndex(token => token.id === editing);
    const token = { id: existing >= 0 ? query.tokens[existing].id : id + '-token-' + ++sequence, label, expression };
    const tokens = [...query.tokens];
    if (existing >= 0) tokens.splice(existing, 1, token); else tokens.push(token);
    query = { ...query, tokens };
    editing = null;
    announcement = existing >= 0 ? 'Filter replaced.' : 'Filter added.';
    commit();
  }
  function connect(container: HTMLElement, rerender: () => void) {
    root = container;
    invalidate = rerender;
    const actions = delegate(container, 'click', '[data-action]', (_event, element) => {
      const action = element.getAttribute('data-action');
      const tokenId = element.getAttribute('data-token-id') || element.closest('[data-token-id]')?.getAttribute('data-token-id');
      if (action === 'search.clear') {
        const field = editor();
        if (field) field.textContent = '';
        query = { text: '', tokens: [] }; editing = null;
        announcement = 'Search cleared.'; commit();
      } else if (action === 'search.token.remove') {
        capture();
        query = { ...query, tokens: query.tokens.filter(token => token.id !== tokenId) };
        announcement = 'Filter removed.'; commit();
      } else if (action === 'search.token.edit' || action === 'search.filter.add') {
        capture();
        const token = query.tokens.find(token => token.id === tokenId);
        editing = token?.id ?? '';
        draft = token?.expression ?? '';
        suggestions = policy.suggest(draft);
        invalidate();
        container.querySelector<HTMLInputElement>('[data-filter-expression]')?.focus();
      } else if (action === 'search.filter.apply') applyFilter();
      else if (action === 'search.suggestion') {
        const suggestion = suggestions.find(item => item.id === element.getAttribute('data-suggestion-id'));
        if (suggestion) applyFilter(suggestion.expression, suggestion.label);
      } else if (action === 'search.filter.cancel') {
        editing = null; announcement = 'Filter editing canceled.'; invalidate(); restoreCaret();
      } else if (action === 'search.submit') { capture(); policy.search(query); }
    });
    const input = delegate(container, 'input', '[role="searchbox"], [data-filter-expression]', (_event, element) => {
      if (element.hasAttribute('data-filter-expression')) {
        const field = element as HTMLInputElement;
        draft = field.value;
        const position = field.selectionStart;
        suggestions = policy.suggest(draft);
        invalidate();
        const next = container.querySelector<HTMLInputElement>('[data-filter-expression]');
        next?.focus(); if (position !== null) next?.setSelectionRange(position, position);
      } else {
        capture();
        policy.search(query);
        // Deliberately no rerender: editable text and caret remain DOM-owned.
      }
    });
    const keyboard = delegate(container, 'keydown', '[role="searchbox"], [data-filter-expression]', (event, element) => {
      const key = event as KeyboardEvent;
      if (key.isComposing) return;
      if (element.hasAttribute('data-filter-expression')) {
        if (key.key === 'Enter') { key.preventDefault(); applyFilter(); }
        if (key.key === 'Escape') { key.preventDefault(); editing = null; invalidate(); restoreCaret(); }
      } else if (key.key === 'Enter') { key.preventDefault(); capture(); policy.search(query); }
    });
    return () => { actions(); input(); keyboard(); root = undefined; invalidate = () => {}; };
  }
  return { render, connect, announceResults(count: number) {
    // Update only the status text while the browser owns the editable search DOM.
    announcement = count + (count === 1 ? ' result.' : ' results.');
    const live = root?.querySelector<HTMLElement>('[role="status"]');
    if (live) live.textContent = announcement;
  } };
}

