.filter-search { min-width:0; color:var(--kui-color-text); }
.filter-edit { border:1px solid var(--kui-color-border); border-radius:var(--kui-radius-m); background:var(--kui-color-surface); }
.filter-edit ul { margin:0; padding:0; list-style:none; display:grid; gap:var(--kui-layout-control-gap); }
.filter-search p { margin:0; }
.filter-edit input { box-sizing:border-box; width:100%; min-width:0; min-height:2.75rem; font:inherit; padding:var(--kui-space-xs); color:var(--kui-color-text); background:var(--kui-color-surface); border:1px solid var(--kui-color-border); border-radius:var(--kui-radius-m); }
.search-button { min-height:2.75rem; font:inherit; padding:var(--kui-space-xs) var(--kui-space-s); color:var(--kui-color-text); background:var(--kui-color-surface); border:1px solid var(--kui-color-border); border-radius:var(--kui-radius-m); }
.filter-search :focus-visible { outline:var(--kui-focus-ring); outline-offset:2px; }
